// @effect-diagnostics nodeBuiltinImport:off - a few small files written once per VS Code start.
/**
 * Installs the T3 Dark / T3 Light theme extension (generated by scripts/friend/vscode-theme.ts)
 * into serve-web's extensions directory before it starts. The extension sets its themes as
 * configuration defaults, so a theme the user picks in VS Code still wins.
 */
import * as NodeCrypto from "node:crypto";
import * as NodeFS from "node:fs";
import * as NodePath from "node:path";

import * as Clock from "effect/Clock";
import * as Effect from "effect/Effect";

import extensionManifest from "./theme/package.json" with { type: "json" };
import darkTheme from "./theme/themes/t3-dark.json" with { type: "json" };
import lightTheme from "./theme/themes/t3-light.json" with { type: "json" };

export const THEME_EXTENSION_ID = `${extensionManifest.publisher}.${extensionManifest.name}`;

const FILES: Record<string, unknown> = {
  "package.json": extensionManifest,
  "themes/t3-dark.json": darkTheme,
  "themes/t3-light.json": lightTheme,
};

/** One entry of VS Code's `extensions.json`; only the fields this module reads are typed. */
interface ManifestEntry {
  readonly identifier?: { readonly id?: string };
  readonly relativeLocation?: string;
  readonly [field: string]: unknown;
}

const isOurs = (entry: ManifestEntry) =>
  entry.identifier?.id?.toLowerCase() === THEME_EXTENSION_ID.toLowerCase();

/** Writes `content` to `path` through a rename, so a crash never leaves half a file. */
const writeAtomically = (path: string, content: string) => {
  const temporary = `${path}.${process.pid}.tmp`;
  NodeFS.writeFileSync(temporary, content);
  NodeFS.renameSync(temporary, path);
};

const readJson = <T>(path: string, missing: T): T =>
  NodeFS.existsSync(path) ? (JSON.parse(NodeFS.readFileSync(path, "utf8")) as T) : missing;

/**
 * Installs the extension under a folder named by its content hash and makes it the only
 * `t3code.t3-theme` in `extensions.json`. Returns false when that exact version was already there.
 * Other extensions and their entries stay untouched.
 */
export const installThemeSync = (extensionsDir: string, now: number): boolean => {
  const contents = Object.entries(FILES).map(
    ([path, content]) => [path, `${JSON.stringify(content, null, 2)}\n`] as const,
  );
  const hash = NodeCrypto.createHash("sha256");
  for (const [path, content] of contents) hash.update(`${path}\0${content}\0`);
  const folderName = `${THEME_EXTENSION_ID}-${extensionManifest.version}-${hash.digest("hex").slice(0, 12)}`;
  const folder = NodePath.join(extensionsDir, folderName);
  const manifestPath = NodePath.join(extensionsDir, "extensions.json");
  // VS Code deletes the folders listed here on its next start, e.g. after an uninstall.
  const obsoletePath = NodePath.join(extensionsDir, ".obsolete");

  NodeFS.mkdirSync(extensionsDir, { recursive: true });
  const manifest = readJson<ManifestEntry[]>(manifestPath, []);
  if (!Array.isArray(manifest)) throw new Error(`${manifestPath} is not a list of extensions`);
  const obsolete = readJson<Record<string, unknown>>(obsoletePath, {});
  const ours = manifest.filter(isOurs);
  if (
    ours.length === 1 &&
    ours[0]?.relativeLocation === folderName &&
    NodeFS.existsSync(NodePath.join(folder, "package.json")) &&
    !(folderName in obsolete)
  ) {
    return false;
  }

  const staging = `${folder}.${process.pid}.tmp`;
  NodeFS.rmSync(staging, { recursive: true, force: true });
  for (const [path, content] of contents) {
    NodeFS.mkdirSync(NodePath.dirname(NodePath.join(staging, path)), { recursive: true });
    NodeFS.writeFileSync(NodePath.join(staging, path), content);
  }
  NodeFS.rmSync(folder, { recursive: true, force: true });
  NodeFS.renameSync(staging, folder);

  const entry: ManifestEntry = {
    identifier: { id: THEME_EXTENSION_ID },
    version: extensionManifest.version,
    location: { $mid: 1, path: folder, scheme: "file" },
    relativeLocation: folderName,
    metadata: { installedTimestamp: now, source: "resource" },
  };
  writeAtomically(
    manifestPath,
    JSON.stringify([...manifest.filter((existing) => !isOurs(existing)), entry]),
  );
  if (folderName in obsolete) {
    const { [folderName]: _restored, ...rest } = obsolete;
    writeAtomically(obsoletePath, JSON.stringify(rest));
  }
  for (const name of NodeFS.readdirSync(extensionsDir)) {
    if (name !== folderName && name.startsWith(`${THEME_EXTENSION_ID}-`)) {
      NodeFS.rmSync(NodePath.join(extensionsDir, name), { recursive: true, force: true });
    }
  }
  return true;
};

/**
 * {@link installThemeSync} as an Effect that never fails: serve-web must not be running, and a
 * theme that cannot be installed leaves VS Code on its own default look.
 */
export const installTheme = Effect.fn("VsCodeTheme.install")(function* (extensionsDir: string) {
  const now = yield* Clock.currentTimeMillis;
  const result = yield* Effect.result(Effect.try(() => installThemeSync(extensionsDir, now)));
  if (result._tag === "Failure") {
    yield* Effect.logWarning(`Cannot install the T3 theme in ${extensionsDir}.`, {
      cause: String(result.failure.cause),
    });
  } else if (result.success) {
    yield* Effect.logInfo("Installed the T3 theme for VS Code.", { extensionsDir });
  }
});
